import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int HPY = scanner.nextInt();
        int ATKY = scanner.nextInt();
        int DEFY = scanner.nextInt();

        int HPM = scanner.nextInt();
        int ATKM = scanner.nextInt();
        int DEFM = scanner.nextInt();

        int h = scanner.nextInt();
        int a = scanner.nextInt();
        int d = scanner.nextInt();

        long minCost = Long.MAX_VALUE;

        // Upper bound for ATK: we need enough to kill the monster in 1 turn.
        // Damage per turn = max(1, ATKY_final - DEFM).
        // Max HPM is 100, max DEFM is 100. Max needed ATKY_final = 200.
        // Max initial ATKY is 100. So loop up to 200.
        for (int finalAtk = ATKY; finalAtk <= 200; finalAtk++) {
            int dmgToMonster = finalAtk - DEFM;
            if (dmgToMonster <= 0) continue; // Cannot kill monster

            // Turns needed to kill monster
            int turns = (HPM + dmgToMonster - 1) / dmgToMonster;

            // Upper bound for DEF: enough to reduce monster damage to 0.
            // Max ATKM is 100. Max needed DEFY_final = 100.
            // Max initial DEFY is 100. So loop up to 100.
            for (int finalDef = DEFY; finalDef <= 100; finalDef++) {
                int dmgToYang = Math.max(0, ATKM - finalDef);
                int totalDmgTaken = turns * dmgToYang;

                // HP needed: totalDmgTaken + 1 (since HP must be > 0 after battle)
                int neededHp = totalDmgTaken + 1;
                int finalHp = Math.max(HPY, neededHp);

                long cost = 0;
                cost += (long) (finalAtk - ATKY) * a;
                cost += (long) (finalDef - DEFY) * d;
                cost += (long) (finalHp - HPY) * h;

                if (cost < minCost) {
                    minCost = cost;
                }
            }
        }

        System.out.println(minCost);
    }
}
